import sqlite3
import json
import concurrent.futures
import sys
from typing import List, Dict, Any

def execute_query(db_path: str, filters: List[Dict[str, Any]]) -> List[List[Any]]:
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM orders")
    rows = cursor.fetchall()
    conn.close()
    return rows

def apply_filters(row: List[Any], filters: List[Dict[str, Any]]) -> bool:
    for filter_obj in filters:
        for key, value in filter_obj.items():
            if row[0] == key and row[1] != value:  # Assuming first column is column name, second is value
                return False
    return True

def process_filters(db_path: str, filters_path: str) -> None:
    with open(filters_path, 'r') as f:
        filters_list = json.load(f)

    rows = execute_query(db_path, filters_list)

    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as executor:
        futures = []
        for filters in filters_list:
            futures.append(executor.submit(apply_filters, rows, filters))

        # This approach is flawed; instead, we'll filter rows per filter set
        pass

    # Correct approach: filter rows for each filter set
    results = []
    for filters in filters_list:
        filtered_rows = []
        for row in rows:
            if all(row[0] == key and row[1] == value for key, value in filters.items()):
                filtered_rows.append(row)
        results.append(filtered_rows)

    # Write results to stdout
    for filtered_rows in results:
        for row in filtered_rows:
            print(json.dumps(dict(zip([col[0] for col in cursor.description], row))))

def main():
    if len(sys.argv) != 3:
        print("Usage: python query_orders.py <database_path> <filters_path>")
        sys.exit(1)

    db_path = sys.argv[1]
    filters_path = sys.argv[2]

    try:
        process_filters(db_path, filters_path)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
